const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Bodoni+Moda:ital,wght@0,400;0,500;1,400&family=Archivo:wght@400;600&display=swap');
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }
::selection { background: #c9a25e; color: #0c0a08; }
a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible { outline: 2px solid #c9a25e; outline-offset: 3px; border-radius: 2px; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; scroll-behavior: auto !important; }
}
input::placeholder, textarea::placeholder { color: #ffffff66; }
input:focus, textarea:focus { border-color: #c9a25e !important; }
::-webkit-scrollbar { width: 9px; } ::-webkit-scrollbar-track { background: #0c0a08; } ::-webkit-scrollbar-thumb { background: #c9a25e66; border-radius: 9px; }
@keyframes shimmer { to { background-position: 200% center; } }
.liquidText { background-image: linear-gradient(100deg,#fff3da,#ffffff,#ffffff,#fff1d6,#fff3da); background-size: 200% auto; color: #fbf4e6; animation: riseIn 1.1s cubic-bezier(.2,.8,.2,1) both, shimmer 5s linear infinite; }
@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .liquidText { -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
}
@keyframes riseIn { 0% { opacity: 0; transform: translateY(28px); filter: blur(6px); } 100% { opacity: 1; transform: translateY(0); filter: blur(0); } }
.rise { animation: riseIn 1.1s cubic-bezier(.2,.8,.2,1) both; }
@keyframes pageIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
.page-in { position: relative; z-index: 4; animation: pageIn .7s cubic-bezier(.16,.84,.44,1) both; }
.marquee { animation: scroll 26s linear infinite; }
@keyframes scroll { to { transform: translateX(-50%); } }
.navlink::after { content: ""; position: absolute; left: 0; bottom: 0; width: 0; height: 1px; background: #c9a25e; transition: width .4s cubic-bezier(.16,.84,.44,1); }
.navlink:hover { color: #c9a25e !important; }
.navlink:hover::after { width: 100%; }
.card { transition: background .6s cubic-bezier(.16,.84,.44,1), transform .6s cubic-bezier(.16,.84,.44,1), box-shadow .6s cubic-bezier(.16,.84,.44,1); }
.card:hover { background: #15120bf2 !important; transform: translateY(-4px); box-shadow: 0 24px 60px -20px #000000cc, inset 0 0 0 1px #c9a25e22; }
.card:hover .sheen { left: 120%; }
.card:hover .card-arrow { opacity: 1 !important; transform: translateX(0) !important; }
.dna-block:hover { background: #14110ccc !important; }
.group-card:hover { background: #14110ccc !important; }
ul li::before { content: "·"; color: #c9a25e; position: absolute; left: 2px; font-weight: 700; }
.svc-row { transition: padding-left .5s cubic-bezier(.16,.84,.44,1), background .5s cubic-bezier(.16,.84,.44,1); } .svc-row:hover { padding-left: 20px; }
.cta-prim { transition: transform .4s cubic-bezier(.16,.84,.44,1), box-shadow .4s cubic-bezier(.16,.84,.44,1), background .4s; } .cta-prim:hover { transform: translateY(-2px); box-shadow: 0 16px 40px -8px #c9a25e66; }
.cta-ghost { transition: background .4s cubic-bezier(.16,.84,.44,1), color .4s cubic-bezier(.16,.84,.44,1), border-color .4s cubic-bezier(.16,.84,.44,1); } .cta-ghost:hover { background: #ece6db; color: #0c0a08 !important; border-color: #ece6db; }
.logo:hover { opacity: .85; }
@keyframes cuePulse { 0%,100% { opacity: .5; transform: translateX(0); } 50% { opacity: 1; transform: translateX(6px); } }
.scroll-cue { animation: cuePulse 2.6s ease-in-out infinite; }
@keyframes menuFade { from { opacity: 0; } to { opacity: 1; } }
.mobile-menu { animation: menuFade .35s ease both; }
@keyframes linkIn { from { opacity: 0; transform: translateX(-18px); } to { opacity: 1; transform: translateX(0); } }
.mobile-link { animation: linkIn .5s cubic-bezier(.16,.84,.44,1) both; }
.mobile-link:hover { color: #c9a25e !important; }
.footlink { transition: color .3s; } .footlink:hover { color: #c9a25e !important; }
.cursor-dot { position: fixed; top: 0; left: 0; width: 6px; height: 6px; margin: -3px 0 0 -3px; border-radius: 50%; background: #c9a25e; pointer-events: none; z-index: 9999; }
.cursor-ring { position: fixed; top: 0; left: 0; width: 34px; height: 34px; margin: -17px 0 0 -17px; border: 1px solid #c9a25e99; border-radius: 50%; pointer-events: none; z-index: 9999; transition: width .3s, height .3s, margin .3s, border-color .3s, background .3s; }
.cursor-ring-hover { width: 56px; height: 56px; margin: -28px 0 0 -28px; border-color: #c9a25e; background: #c9a25e1a; }
body.has-custom-cursor, body.has-custom-cursor * { cursor: none !important; }
.curtain { position: fixed; inset: 0; z-index: 60; background: #0c0a08; transform: scaleY(0); transform-origin: bottom; pointer-events: none; display: flex; align-items: center; justify-content: center; }
.curtain-mark { font-family: 'Bodoni Moda', serif; font-size: 60px; letter-spacing: 8px; color: #c9a25e; opacity: 0; }
.curtain-on { animation: curtainSweep .62s cubic-bezier(.7,0,.3,1) forwards; }
.curtain-on .curtain-mark { animation: markFlash .62s ease forwards; }
@keyframes curtainSweep { 0% { transform: scaleY(0); transform-origin: bottom; } 45% { transform: scaleY(1); transform-origin: bottom; } 55% { transform: scaleY(1); transform-origin: top; } 100% { transform: scaleY(0); transform-origin: top; } }
@keyframes markFlash { 0%,100% { opacity: 0; } 50% { opacity: 1; } }
@media (pointer: coarse) { .cursor-dot, .cursor-ring { display: none !important; } }
@media (max-width: 860px) {
  .desktop-nav { display: none !important; }
  .burger { display: block !important; }
  footer > div:first-child { grid-template-columns: 1fr !important; }
  .svc-row { grid-template-columns: 70px 1fr !important; }
  .dna-block { grid-template-columns: 1fr !important; }
  .dna-block > div:first-child { border-right: none !important; border-bottom: 1px solid #ffffff14; padding-bottom: 20px; }
  .group-card { grid-template-columns: 1fr !important; }
  .group-card > div:first-child { min-height: 64px; border-right: none !important; border-bottom: 1px solid #ffffff14; }
}
`;
